const item = $input.first().json;
const amountRaw = item.amount;
const amount = typeof amountRaw === 'number' ? amountRaw : parseFloat(amountRaw);
const from = (item.from_currency || '').toString().trim().toUpperCase();
const to = (item.to_currency || '').toString().trim().toUpperCase();
const codePattern = /^[A-Z]{3}$/;

if (amountRaw === undefined || amountRaw === null || amountRaw === '' || Number.isNaN(amount)) {
  return [{ json: { valid: false, success: false, error_code: 'INVALID_AMOUNT', message: `"${amountRaw}" is not a valid number for amount.` } }];
}
if (amount <= 0) {
  return [{ json: { valid: false, success: false, error_code: 'NON_POSITIVE_AMOUNT', message: 'The amount to convert must be greater than zero.' } }];
}
if (!codePattern.test(from) || !codePattern.test(to)) {
  return [{ json: { valid: false, success: false, error_code: 'INVALID_CURRENCY_CODE', message: 'Currency codes must be 3-letter codes, e.g. USD, EUR, JPY.' } }];
}
return [{ json: { valid: true, amount, from_currency: from, to_currency: to } }];

const validated = $('Code - Validate Conversion Input').first().json;
const amount = validated.amount;
const from = validated.from_currency;
const to = validated.to_currency;
const baseCurrency = 'USD';
const STALE_THRESHOLD_HOURS = 36; // loader runs daily; tolerates one missed/delayed run before warning
const rows = $input.all().map(i => i.json).filter(r => r && r.target_currency);

if (rows.length === 0 && from !== baseCurrency && to !== baseCurrency) {
  return [{ json: { success: false, error_code: 'NO_RATE_DATA', message: 'No exchange rate data has been loaded yet. Please try again after the daily rate loader has run.' } }];
}

function findRate(code) {
  if (code === baseCurrency) return { rate: 1, fetched_at: null };
  const row = rows.find(r => r.target_currency === code);
  return row ? { rate: Number(row.rate), fetched_at: row.fetched_at } : null;
}

const fromRate = findRate(from);
const toRate = findRate(to);

if (!fromRate) {
  return [{ json: { success: false, error_code: 'UNKNOWN_CURRENCY', message: `"${from}" is not a supported currency code.` } }];
}
if (!toRate) {
  return [{ json: { success: false, error_code: 'UNKNOWN_CURRENCY', message: `"${to}" is not a supported currency code.` } }];
}

const effectiveRate = toRate.rate / fromRate.rate;
const convertedAmount = amount * effectiveRate;
const fetchedTimestamps = [fromRate.fetched_at, toRate.fetched_at].filter(Boolean).sort();
const fetchedAt = fetchedTimestamps.length ? fetchedTimestamps[0] : null;
const ageHours = fetchedAt ? (Date.now() - new Date(fetchedAt).getTime()) / 3600000 : null;
const isStale = ageHours !== null && ageHours > STALE_THRESHOLD_HOURS;

return [{
  json: {
    success: true,
    amount,
    from_currency: from,
    to_currency: to,
    converted_amount: Math.round(convertedAmount * 1e6) / 1e6,
    rate: Math.round(effectiveRate * 1e6) / 1e6,
    fetched_at: fetchedAt,
    is_stale: isStale
  }
}];
